files.content:
.pagination{
  display:flex;
  align-items:center;
  gap:var(--s-1);
}
.pagination-list{
  list-style:none;
  margin:0;
  padding:0;
  display:flex;
  align-items:center;
  gap:var(--s-1);
}
.pagination-link{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--s-2);
  box-sizing:border-box;
  min-width:var(--s-8);
  height:var(--s-8);
  padding:0 var(--s-2);
  border:var(--bw-1) solid transparent;
  border-radius:var(--r-md);
  background:transparent;
  color:var(--obsidian-300);
  font:inherit;
  font-size:var(--t-small);
  font-variant-numeric:tabular-nums;
  text-decoration:none;
  cursor:pointer;
  transition:background var(--d-quick) var(--ease-standard),color var(--d-quick) var(--ease-standard);
}
.pagination-link:hover{
  background:var(--obsidian-700);
  color:var(--obsidian-100);
}
.pagination-link:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-px);
  box-shadow:var(--ring-halo);
  color:var(--obsidian-100);
}
.pagination-link[aria-current="page"]{
  background:var(--obsidian-700);
  border-color:var(--obsidian-500);
  color:var(--obsidian-100);
  font-weight:600;
  cursor:default;
}
.pagination-link[aria-disabled="true"]{
  opacity:var(--opacity-disabled);
  cursor:not-allowed;
  pointer-events:none;
}
.pagination-gap{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-width:var(--s-8);
  color:var(--obsidian-300);
  font-size:var(--t-small);
}
.pagination-status{
  padding:0 var(--s-3);
  color:var(--obsidian-300);
  font-size:var(--t-small);
  font-variant-numeric:tabular-nums;
}
@media (max-width:480px){
  .pagination{
    flex-wrap:wrap;
  }
  .pagination-link > span{
    display:none;
  }
  .pagination-gap{
    min-width:var(--s-6);
  }
}
@media (prefers-reduced-motion:reduce){
  .pagination-link{
    transition:none;
  }
}
